-- Phase B — the 257 canonical workflow steps
--
-- Generated by scripts/phase_b/gen_migration.mjs from the checksummed package under
-- docs/phase-b/package/.  Do not hand-edit: scripts/checks/phase_b_migration_matches_package.test.mjs
-- regenerates this file and fails on any difference.
--
-- This file writes registry rows only.  It creates no cron job, no provider route, no
-- autonomous executor and no business record.

set lock_timeout = '8s';
set statement_timeout = '600s';


-- One accountable owner per step, enforced three ways: step_id is the primary key so a step
-- cannot appear twice; accountable_role_id is NOT NULL so it cannot appear unowned; and
-- a10_phase_b_owner_guard refuses an owner that does not resolve to an active canonical role.
--
-- is_closure_step is derived as (step_type = 'closure' OR next_step_if_pass = 'WORKFLOW_COMPLETE').
-- Those two select the same step for 29 of the 30 workflows; W22 is the exception, and the
-- reason is recorded in phase_b_package_erratum.
on conflict (step_id) do update set workflow_id = excluded.workflow_id, step_no = excluded.step_no, step_name = excluded.step_name, step_type = excluded.step_type, accountable_role_id = excluded.accountable_role_id, package_accountable_token = excluded.package_accountable_token, actor_kind = excluded.actor_kind, contributors = excluded.contributors, independent_reviewer_role_id = excluded.independent_reviewer_role_id, entry_condition = excluded.entry_condition, required_inputs = excluded.required_inputs, required_action = excluded.required_action, required_output = excluded.required_output, acceptance_criteria = excluded.acceptance_criteria, closure_criteria = excluded.closure_criteria, failure_or_block_state = excluded.failure_or_block_state, founder_gate = excluded.founder_gate, idempotency_scope = excluded.idempotency_scope, repeatable = excluded.repeatable, is_closure_step = excluded.is_closure_step, next_step_if_pass = excluded.next_step_if_pass, next_step_if_fail = excluded.next_step_if_fail, success_workflow_state = excluded.success_workflow_state, failure_workflow_state = excluded.failure_workflow_state, notes = excluded.notes;
